import * as T from 'three';
export function makeCity(scene){
 const roofs=[];const materials=[0x39465e,0x536079,0x665b75,0x425b6e].map(color=>new T.MeshStandardMaterial({color,roughness:.85}));
 const roofMaterial=new T.MeshStandardMaterial({color:0x7991a8,roughness:.9});
 function block(x,z,w,d,h,index){const building=new T.Mesh(new T.BoxGeometry(w,h,d),materials[index%materials.length]);building.position.set(x,-h/2-.25,z);building.castShadow=true;building.receiveShadow=true;scene.add(building);const roof=new T.Mesh(new T.BoxGeometry(w,.5,d),roofMaterial);roof.position.set(x,0,z);roof.receiveShadow=true;scene.add(roof);
 for(let row=0;row<4;row++)for(let c=0;c<3;c++){const light=new T.Mesh(new T.PlaneGeometry(.7,1),new T.MeshBasicMaterial({color:row%2?0xffc974:0xa3d9ff}));light.position.set(x-w/2+.9+c*2,-2-row*2,z+d/2+.01);scene.add(light)}
 return roof;
 }
 for(let i=0;i<70;i++){const z=-i*30;block(0,z,18,22,22+i%5*3,i);roofs.push({z,min:z-11,max:z+11,width:18});for(const side of [-1,1])block(side*(25+i%3*3),z-4,12+i%3*2,19,30+i%7*4,i+1);}
 const street=new T.Mesh(new T.PlaneGeometry(150,2300),new T.MeshStandardMaterial({color:0x172335}));street.rotation.x=-Math.PI/2;street.position.set(0,-32,-1000);scene.add(street);
 return {onRoof:(x,z)=>Math.abs(x)<8.7&&roofs.some(r=>z>=r.min&&z<=r.max),end:-2040};
}

